from h34 import *
M=mcq;F=tf;S=short;N=num
# angle types
b=''
for vx,ang,name,col in [(60,30,'Acute angle (less than a right angle)','#2e86ab'),(330,90,'Right angle (like a corner of a book)','#3a9d5d'),(590,135,'Obtuse angle (more than a right angle)','#e4572e')]:
    import math
    r=130; a=math.radians(ang); x2=vx+r*math.cos(a); y2=150-r*math.sin(a)
    b+=f'<line x1="{vx}" y1="150" x2="{vx+r}" y2="150" stroke="{col}" stroke-width="5"/><line x1="{vx}" y1="150" x2="{x2:.0f}" y2="{y2:.0f}" stroke="{col}" stroke-width="5"/><circle cx="{vx}" cy="150" r="5" fill="#222"/>'
    if ang==90: b+=f'<rect x="{vx}" y="130" width="20" height="20" fill="none" stroke="#222" stroke-width="2"/>'
    else:
        ax=vx+36*math.cos(a); ay=150-36*math.sin(a); b+=f'<path d="M{vx+36} 150 A36 36 0 0 0 {ax:.0f} {ay:.0f}" fill="none" stroke="#222" stroke-width="2"/>'
    b+=f'<text x="{vx}" y="190" font-size="14" fill="{col}">{name}</text>'
svgfile('c4-maths-angle-types.svg',760,205,b)
# circle parts
b='<circle cx="200" cy="120" r="90" fill="#fdf3d8" stroke="#333" stroke-width="3"/><line x1="110" y1="120" x2="290" y2="120" stroke="#c0392b" stroke-width="4"/><line x1="200" y1="120" x2="264" y2="56" stroke="#2e86ab" stroke-width="4"/><circle cx="200" cy="120" r="5" fill="#222"/><text x="188" y="145" font-size="15">Centre</text><text x="238" y="100" font-size="15" fill="#2e86ab">radius</text><text x="120" y="112" font-size="15" fill="#c0392b">diameter</text><text x="340" y="80" font-size="15">The diameter passes through the centre.</text><text x="340" y="108" font-size="15">Diameter = 2 x radius.</text><text x="340" y="136" font-size="15">Radius = half of the diameter.</text><text x="340" y="164" font-size="15">All radii of a circle are equal.</text>'
svgfile('c4-maths-circle-parts.svg',700,235,b)
chapter(4,'maths','shapes-around-us','Shapes Around Us',
 ('Diksha and India Gate','Diksha went to Delhi with her father in the summer holidays. They saw the India Gate, Qutub Minar, Safdarjung Tomb, Akshardham, the National Museum, Jantar Mantar and Sansad Bhawan. Back at home she tried to build a model of India Gate with her wooden blocks. Which blocks would you pick for the pillars, the base and the top? In this chapter you will build with solid shapes, count their faces, corners and edges, meet angles and circles, and solve puzzling shape problems.'),
 [('Building models with shapes',['To make a model of a building, first decide which parts you want to show, such as the roof, the pillars and the base.','Then ask yourself why you chose those parts and which shape will model each part well.','Compare your model with the real building: some things look the same and some are different, and both are worth noticing.','If you take away one piece of the model, does it still look like the building? Every piece matters, and you can always improve a model.','The Qutub Minar is a World Heritage site and the tallest building made of bricks. It has 5 storeys and 379 stairs.','Long ago people built with clay bricks, stone blocks and wood. Today we also use concrete blocks and hollow blocks. All these blocks have flat faces and straight edges.']),
  ('Nets, prisms and pyramids',['If you open a box and flatten it, you get its net. When you fold the net along the dotted lines you get the box back.','A prism has two matching faces at the two ends, joined by rectangle faces. The triangular prism, the square prism and the hexagonal prism are examples.','A pyramid has one base, and all its triangular faces meet at one point at the top. The triangular pyramid, the square pyramid and the pentagonal pyramid are examples.','So a rectangle face is common to all the prisms, and a triangle face is common to all the pyramids.','The difference is simple: a prism has two matching ends, but a pyramid has only one base and a pointed top.','A cube is a special prism, because its two ends are squares joined by square faces. Square prism is another name for a cube or cuboid shape with square ends.']),
  ('Faces, corners and edges',['The flat parts of a solid are called its faces, the pointed places where edges meet are its corners, and the lines where two faces meet are its edges.','We write F for faces, V for corners and E for edges. A cube has 6 faces, 8 corners and 12 edges, and a cuboid has the same numbers.','A triangular pyramid has 4 faces, 4 corners and 6 edges, and a square pyramid has 5 faces, 5 corners and 8 edges.','A triangular prism has 5 faces, 6 corners and 9 edges.','Now calculate F + V - E for each shape. For the cube it is 6 + 8 - 12 = 2, and for the square pyramid it is 5 + 5 - 8 = 2.','You will find the answer is 2 for every one of these solids. That is a lovely pattern hiding inside all of them.','You can make these shapes with straws as edges and plasticine balls as corners, and then count to check.']),
  ('Sorting 3D shapes',['We can sort solids in many ways. One way is by the number of flat faces: a cone has 1 flat face, a cylinder has 2, a triangular pyramid has 4, a square pyramid and a triangular prism have 5, and a cube and a cuboid have 6.','Another way is by the number of straight edges: a triangular pyramid has 6, a square pyramid has 8, a triangular prism has 9, and a cube or a cuboid has 12.','We can also sort by curved faces. A sphere, a cone and a cylinder have curved faces, while the cube, cuboid, prisms and pyramids have only flat faces.','Some shapes fit in two groups at the same time, and circles drawn overlapping each other help us show this, like a Venn diagram.','A shape that has both rectangular and triangular faces, like a triangular prism, goes in the place where the circles overlap.']),
  ('Looking carefully at a cube',['Take a die. The face with number 1 is opposite the face with number 6, 2 is opposite 5, and 3 is opposite 4. Opposite faces always add up to 7.','The face numbered 1 shares an edge with four faces, which are 2, 3, 4 and 5. It has no common edge with the face numbered 6.','If you see three different views of the same coloured cube, you can work out which colour is opposite which, by finding the faces that never touch.','You can also build models and towers with cubes and count how many cubes are used, including the hidden ones at the bottom.']),
  ('Guess the solid from clues',['We can name a solid from clues. A solid with 5 faces, 5 corners and 8 edges, with one square face and 4 triangle faces, is a square pyramid.','A solid with 1 flat face, 1 curved face and 1 edge is a cone. A solid with 1 curved face and no edges or corners is a sphere.','A solid with 2 flat faces, 1 curved face, 2 edges and no corners is a cylinder. A solid with 5 faces, 6 corners and 9 edges, two of its faces triangles, is a triangular prism. A solid with 6 faces, 12 edges and 8 corners is a cube or a cuboid.']),
  ('When lines meet: angles',['Take two straws and join them at one end. The two straws are like two lines that meet at a point. When two lines meet they make an angle.','We see angles everywhere: in the corners of a house drawing, in a boat drawing, in the hands of a clock and even in yoga postures.','Look around the classroom and find angles at the corners of the board, the door, the windows and the desks.']),
  ('Right, acute and obtuse angles',['Fold a piece of paper twice to make a corner. This is a right angle checker. The corner of a book or a window is a right angle.','An angle that is smaller than a right angle is an acute angle. An angle that is bigger than a right angle is an obtuse angle.','To check an angle, place the paper corner on it. If the angle fits exactly, it is a right angle. If the angle is smaller, it is acute, and if it is bigger, it is obtuse.','In letters too we can find angles. The letter L has a right angle, the letter V has an acute angle, and the open end of a leaning letter can make an obtuse angle.','On a dot grid you can draw right angles, acute angles and obtuse angles and then check them with your checker.']),
  ('Shapes with straws',['Make a triangle with straws and clay. Gently push one side. The triangle does not change its shape, and we say a triangle is rigid. This is why bridges and roofs use triangles.','Now make a rectangle with straws. When you push one side, the shape changes. The right angles are not right angles any more, and two angles become acute while two become obtuse.','A square behaves the same way: push it and it changes into a slanted shape. So triangles are rigid but four-sided shapes are not.','A pentagon has 5 sides. If its sides are equal and you push one side, the pentagon changes its shape too, and the angles change.','A square is a special rectangle, because all its sides are equal. A square has four right angles, like a rectangle.']),
  ('Circles',['Mark a point A. Draw many points at the same distance from A and join them freehand. You get a circle. The point A is the centre.','The line from the centre to the border of the circle is called the radius. All radii of a circle are equal.','If you take a circular paper, fold it in half and open it, the crease passes through the centre. Fold it in half in different ways and every crease has the same length. These creases are the diameters.','A diameter goes from one side of the circle to the other through the centre. Every diameter passes through the centre, so all diameters are equal in length.','The length of the diameter is double the length of the radius, and the radius is half of the diameter.','A compass helps us draw perfect circles. Keep the point on the centre and turn the pencil around. If you change the opening of the compass, you get a bigger or a smaller circle.','A wheel is a circle. A wheel with a longer radius also has a longer diameter, and a wheel with a shorter radius has a shorter diameter.']),
  ('Puzzling shapes',['Look at a picture and find the hidden shapes. You can find triangles, rectangles and squares hiding inside each other.','You can draw 2 lines to cut a triangle into 1 square and 2 triangles, or draw 2 lines to divide a square into 3 triangles.','With 5 matchsticks you can make 2 triangles, because the two triangles share one stick. If you move two sticks you can get 4 triangles.','Look at shapes with 3, 4 and 5 sides. A shape with 3 sides has 3 angles, a shape with 4 sides has 4 angles, and a shape with 5 sides has 5 angles. The number of sides and the number of angles are always the same.','Squiggly the spider walks along her triangle web. She wants to return to the start without walking on any wall twice, so planning the path is a puzzle in itself.'])],
 [('Find F + V - E for a triangular prism.',[('A triangular prism has 5 faces, 6 corners and 9 edges.','Count each part of the solid carefully.'),('F + V - E = 5 + 6 - 9.','Put the numbers in the pattern.'),('5 + 6 = 11 and 11 - 9 = 2.','Add first, then subtract. The answer is 2, just like every other solid.')]),
  ('Which solid has 5 faces, 5 corners and 8 edges, with one square face?',[('Only two common solids have 5 faces: the triangular prism and the square pyramid.','Start with the number of faces.'),('The prism has 6 corners and 9 edges, so it does not match.','Compare corners and edges.'),('The square pyramid has 5 corners and 8 edges, a square base and 4 triangle faces.','So the solid is a square pyramid.')]),
  ('Can you make a model with 10 straws and 6 clay balls? Which solid is it?',[('Straws are edges and clay balls are corners, so E = 10 and V = 6.','Match straws with edges and balls with corners.'),('F + V - E = 2, so F + 6 - 10 = 2, which means F = 6.','Use the pattern to find the faces.'),('A solid with 6 faces, 6 corners and 10 edges is a pentagonal pyramid: one pentagon and 5 triangles.','So you can make a pentagonal pyramid.')]),
  ('The diameter of a round plate is 12 cm. What is its radius? If the radius of a wheel is 9 cm, what is its diameter?',[('The radius is half of the diameter, so 12 divided by 2 = 6 cm.','Halve the diameter to get the radius.'),('The diameter is double the radius, so 9 + 9 = 18 cm.','Double the radius to get the diameter.')])],
 ('Explain the difference between a prism and a pyramid, tell what an acute, right and obtuse angle are, and name the parts of a circle.',['A prism has two matching ends joined by rectangles; a pyramid has one base and triangles meeting at a point','Acute is smaller than a right angle, obtuse is bigger','A circle has a centre, a radius and a diameter, and the diameter is double the radius','A cube has 6 faces, 8 corners and 12 edges'],['A cube is not a prism','A rectangle is rigid','The diameter is the same as the radius']),
 ['Solid shapes have faces, edges and corners. F + V - E is 2 for these solids.','A prism has two matching ends; a pyramid has triangular faces meeting at a point.','Two lines meeting make an angle: acute is smaller than a right angle, obtuse is bigger.','A triangle is rigid, but a rectangle or square changes shape when pushed.','A circle has a centre, radius and diameter; the diameter is double the radius.'],
 [M('1',1,'How many faces does a cube have?','6',[('4','A cube is not that small'),('8','A cube has 8 corners, not 8 faces')],'A cube has 6 square faces, 8 corners and 12 edges.'),
  N('2',1,'How many edges does a square pyramid have?',8,'It has 4 edges on the base and 4 edges going up to the top point.',[(5,'5 is the number of faces and corners')]),
  F('3',1,'A cube is also a kind of prism.',True,'A cube is a square prism, because its two opposite ends are squares joined by square faces.'),
  M('4',1,'Which solid has 1 flat face, 1 curved face and 1 edge?','Cone',[('Cylinder','A cylinder has 2 flat faces'),('Sphere','A sphere has no flat face')],'A cone has a flat round base, a curved face and one edge.'),
  M('5',2,'An angle smaller than a right angle is called a(n) ___ angle.','acute',[('obtuse','Obtuse angles are bigger than a right angle'),('straight','A straight angle is a flat line, not smaller than a right angle')],'Acute means smaller than a right angle.'),
  N('6',2,'What is F + V - E for a cuboid?',2,'A cuboid has 6 faces, 8 corners and 12 edges, so 6 + 8 - 12 = 2.',[(14,'You added edges instead of subtracting them')]),
  M('7',2,'On a die, which face is opposite the face numbered 2?','5',[('4','4 is opposite 3'),('6','6 is opposite 1')],'Opposite faces of a die add up to 7, so 2 is opposite 5.'),
  M('8',2,'Which shape does not change its form when you gently push one side?','Triangle',[('Rectangle','A rectangle slants when pushed'),('Square','A square also slants when pushed')],'A triangle is rigid, so bridges and roofs use triangles.'),
  N('9',2,'The radius of a wheel is 9 cm. What is its diameter in cm?',18,'The diameter is double the radius, so 9 x 2 = 18 cm.',[(9,'That is the radius itself'),(4.5,'You halved the radius instead of doubling it')],'cm'),
  S('10',3,'What do we call the flat shape you get by opening up a box?',['net','a net'],'Opening and flattening a box shows its net.'),
  M('11',3,'A shape has 5 sides. How many angles does it have?','5',[('4','A 4-sided shape has 4 angles'),('3','A 3-sided shape has 3 angles')],'The number of angles is always equal to the number of sides.'),
  M('12',3,'Which solid can you make with 12 straws and 8 clay balls?','Cube',[('Triangular prism','It needs 9 straws and 6 balls'),('Square pyramid','It needs 8 straws and 5 balls')],'Straws are edges and balls are corners. A cube has 12 edges and 8 corners.')],
 svgs=[('c4-maths-fve-table','A table lists faces, corners and edges for five solids, and F + V - E is 2 in every row.','F + V - E equals 2 for these solids.'),('c4-maths-angle-types','Three pairs of lines meeting at a point show an acute angle, a right angle and an obtuse angle.','Acute is smaller than a right angle; obtuse is bigger.'),('c4-maths-circle-parts','A circle with its centre, a radius and a diameter marked.','The diameter passes through the centre and is double the radius.')],
 keep=['prism','pyramid','net','angle','radius','diameter'])
